public class Point3DTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String str(Object o) {
        return o == null ? null : o.toString();
    }

    public static void main(String[] args) {
        Point3D p = new Point3D(1.0, 2.0, 3.0);
        check("toString of (1,2,3)", "(1.0, 2.0, 3.0)", str(p));

        Point3D moved = p.translate(1.0, -2.0, 0.5);
        check("translate returns shifted point", "(2.0, 0.0, 3.5)", str(moved));
        check("translate returns a NEW object", true, moved != null && moved != p);
        check("original is unchanged", "(1.0, 2.0, 3.0)", str(p));

        Point3D origin = new Point3D(0.0, 0.0, 0.0);
        check("translate from origin", "(5.0, -1.5, 2.0)", str(origin.translate(5.0, -1.5, 2.0)));
        check("origin still at origin", "(0.0, 0.0, 0.0)", str(origin));

        Object chained;
        try {
            Point3D q = p.translate(1.0, 1.0, 1.0).translate(1.0, 1.0, 1.0);
            chained = str(q);
        } catch (RuntimeException e) {
            chained = "exception";
        }
        check("two translates chain", "(3.0, 4.0, 5.0)", chained);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

